<script>
import { projects } from '../mock/threeSame'
const empty = () => ({ project: '', owner: '', fileType: '报告书', approvalUnit: '', approvalDate: '', approvalNo: '', acceptance: '', permitStart: '', permitEnd: '', emergencyStart: '', emergencyEnd: '', drainageStart: '', drainageEnd: '' })
export default { name: 'ThreeSameList', props: { type: { type: String, default: 'environment' } }, data () { return { activeType: 'three-same', type: this.type, rows: projects, filters: { project: '', status: '', date: null, createRange: [] }, statusOptions: ['已完成', '部分完成', '待验收', '资料不完整'], page: 1, pageSize: 5, uploadVisible: false, dialogVisible: false, dialogMode: 'view', dialogRow: null, dialogForm: empty(), permitRange: [], emergencyRange: [], drainageRange: [], rules: { project: [{ required: true, message: '请输入项目名称', trigger: 'blur' }] } } }, computed: { filteredRows () { return this.rows.filter(r => (!this.filters.project || r.project.indexOf(this.filters.project) > -1) && (!this.filters.status || r.status === this.filters.status) && this.inCreateRange(r)) }, pagedRows () { return this.filteredRows.slice((this.page - 1) * this.pageSize, this.page * this.pageSize) }, dialogTitle () { return this.dialogMode === 'view' ? '查看环保三同时项目' : this.dialogMode === 'edit' ? '编辑环保三同时项目' : '新增环保三同时项目' } }, methods: { createTime (row) { return ({ 1: '2026-01-08', 2: '2026-01-08', 3: '2026-01-09', 4: '2026-01-09', 5: '2026-01-10', 6: '2026-01-10', 7: '2026-01-11', 8: '2026-01-11', 9: '2026-01-12' }[row.id] || '-') }, inCreateRange (row) { if (!this.filters.createRange || this.filters.createRange.length !== 2) return true; const value = this.createTime(row); return value >= this.filters.createRange[0] && value <= this.filters.createRange[1] }, selectCategory (name) { this.$router.push('/three-same/' + name) }, switchType (tab) { if (tab.name === 'safety' || tab.name === 'health') this.$router.push('/three-same/' + tab.name) }, reset () { this.filters = { project: '', status: '', date: null } }, attachmentText (row) { const count = { 1: 3, 2: 2, 3: 2, 4: 1, 5: 0, 6: 1, 7: 2, 8: 0, 9: 3 }[row.id] || 0; return count ? '已上传 ' + count + ' 个' : '未上传' }, showAttachments (row) { const count = this.attachmentText(row); this.$alert(row.project + '<br><br>附件资料：' + count + '<br>可在编辑弹窗中继续上传